namespace Flagman;
public static class OfferPublication
{
 public static OfferOverride Set(State s,string id,OfferInput input,Actor actor,DateTimeOffset now){AccessService.RequireRole(actor,"manager");Inventory.Require(s.Dishes.Any(x=>x.Id==id&&!x.Archived),"Блюдо не найдено",404);Inventory.Require(input.Visibility is "auto" or "show" or "hide"&&(input.WaiterNote==null||input.WaiterNote.Length<=240),"Видимость auto/show/hide; пояснение до 240 символов");var old=s.OfferOverrides.Find(x=>x.Id==id);Inventory.Require((old?.Version??0)==input.ExpectedVersion,"Настройка изменилась",409);var result=new OfferOverride(id,input.Visibility,input.Emphasized,input.WaiterNote,(old?.Version??0)+1);s.OfferOverrides.RemoveAll(x=>x.Id==id);s.OfferOverrides.Add(result);AccessService.Audit(s,actor,"offer.changed",id,now);return result;}
 public static List<PublishedOffer> Build(State s,DateTimeOffset now){var auto=Insights.Recommendations(s,now).Ranking.Select(x=>x.DishId).ToHashSet();return s.Dishes.Where(d=>!d.Archived).Select(d=>{var o=s.OfferOverrides.Find(x=>x.Id==d.Id);var n=Inventory.Portions(s,d,now);return new PublishedOffer(d.Id,d.Name,d.Category,n,o?.Visibility??"auto",o?.Emphasized??false,o?.WaiterNote,n==0?"Нет пригодных ингредиентов":null);}).Where(x=>x.Visibility=="show"||x.Visibility=="auto"&&auto.Contains(x.DishId)).OrderByDescending(x=>x.Emphasized).ThenBy(x=>x.Name).ToList();}
}
